import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

const { fontFamily: montserratFamily } = loadMontserrat();



export type LifterComparisonProps = Record<string, any>;

// Helper component for stacked set blocks
const SetBlocks: React.FC<{
  count: number;
  color: string;
  delay: number;
  frame: number;
  fps: number;
}> = ({ count, color, delay, frame, fps }) => {
  return (
    <div
      style={{
        display: "flex",
        flexDirection: "row",
        gap: "10px",
        height: "60px",
        alignItems: "flex-end",
      }}
    >
      {Array.from({ length: count }).map((_, i) => {
        const blockDelay = delay + i * 5;
        const scale = spring({
          frame: frame - blockDelay,
          fps,
          config: { damping: 12, mass: 0.5 },
        });
        const opacity = interpolate(frame - blockDelay, [0, 10], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

        return (
          <div
            key={i}
            style={{
              width: "40px",
              height: "100%",
              backgroundColor: color,
              borderRadius: "8px",
              transform: `scaleY(${scale})`,
              transformOrigin: "bottom",
              opacity,
              boxShadow: `0 0 15px ${color}40`,
            }}
          />
        );
      })}
    </div>
  );
};

// Helper component for animated progress bars
const MetricBar: React.FC<{
  label: string;
  percentage: number; // 0 to 1
  color: string;
  delay: number;
  frame: number;
  fps: number;
  textColor: string;
}> = ({ label, percentage, color, delay, frame, fps, textColor }) => {
  const containerOpacity = interpolate(frame - delay, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const fillProgress = spring({
    frame: frame - delay - 10,
    fps,
    config: { damping: 20 },
  });

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "8px",
        opacity: containerOpacity,
        width: "100%",
      }}
    >
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          fontFamily: montserratFamily,
          color: textColor,
          fontSize: "24px",
          fontWeight: 600,
        }}
      >
        <span>{label}</span>
        <span style={{ opacity: 0.7 }}>{Math.round(percentage * 100)}%</span>
      </div>
      <div
        style={{
          width: "100%",
          height: "24px",
          backgroundColor: "rgba(255, 255, 255, 0.1)",
          borderRadius: "12px",
          overflow: "hidden",
        }}
      >
        <div
          style={{
            width: `${percentage * 100}%`,
            height: "100%",
            backgroundColor: color,
            borderRadius: "12px",
            transform: `scaleX(${fillProgress})`,
            transformOrigin: "left",
            boxShadow: `0 0 15px ${color}60`,
          }}
        />
      </div>
    </div>
  );
};

